import React from "react";
import { useNavigate } from "react-router-dom";
import "../style/Results.css";

function Results() {
  const navigate = useNavigate();

  return (
    <div className="results-container">
      <h1 className="results-title">نتائج التحليل</h1>

      <p className="results-description">
        الخوارزمية الجينية اختارت المجموعة المثلى من الخصائص الطبية التي تحقق أفضل دقة للنموذج.
      </p>

      <div className="results-box">
        <p>عدد الخصائص المختارة: <strong>6</strong></p>
        <p>دقة النموذج: <strong>94%</strong></p>
      </div>

      <button onClick={() => navigate("/")} className="results-btn">
        العودة إلى الصفحة الرئيسية
      </button>
    </div>
  );
}
export default Results;
